1	package net.officefloor.hq.app.period;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.time.YearMonth;
6	import java.util.ArrayList;
7	import java.util.Comparator;
8	import java.util.LinkedHashMap;
9	import java.util.List;
10	import java.util.Locale;
11	import java.util.Map;
12	import java.util.stream.Collectors;
13	import net.officefloor.hq.app.Audit;
14	import net.officefloor.hq.app.claim.Claim;
15	import net.officefloor.hq.app.claim.ClaimRepository;
16	import net.officefloor.hq.app.claim.ClaimStatus;
17	import net.officefloor.hq.app.claim.Dues;
18	import net.officefloor.hq.app.person.Person;
19	import net.officefloor.hq.app.person.PersonRepository;
20	import net.officefloor.hq.app.role.Role;
21	import net.officefloor.hq.app.role.RoleService;
22	import net.officefloor.hq.app.sheet.Sheet;
23	import net.officefloor.hq.app.sheet.SheetService;
24	import net.officefloor.hq.app.sheet.TodayChanged;
25	import org.springframework.context.event.EventListener;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.stereotype.Service;
28	import org.springframework.transaction.annotation.Transactional;
29	import org.springframework.web.server.ResponseStatusException;
30	
31	/** The periods on a sheet: listed, added, closed and reopened. */
32	@Service
33	public class PeriodService {
34	
35	    private final PeriodRepository periods;
36	    private final ClaimRepository claims;
37	    private final PersonRepository people;
38	    private final Dues dues;
39	    private final SheetService sheets;
40	    private final RoleService roles;
41	    private final Audit audit;
42	
43	    public PeriodService(PeriodRepository periods, ClaimRepository claims, PersonRepository people, Dues dues,
44	            SheetService sheets, RoleService roles, Audit audit) {
45	        this.periods = periods;
46	        this.claims = claims;
47	        this.people = people;
48	        this.dues = dues;
49	        this.sheets = sheets;
50	        this.roles = roles;
51	        this.audit = audit;
52	    }
53	
54	    /** The sheet's periods by from-date. */
55	    @Transactional(readOnly = true)
56	    public List<Period> list(String sheetId) {
57	        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
58	    }
59	
60	    /**
61	     * Add a period to the sheet; refused when its from-date is after its to-date, when its name is
62	     * already in use on the sheet, or when it shares a day with another period. A cap, when given,
63	     * is the most OPEN or PENDING claims due by in it a person may have (see {@link #refuseIfCapped});
64	     * it must be at least 1, and PERIOD_ADDED ends with cap=&lt;n&gt;.
65	     */
66	    @Transactional
67	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to, Integer cap) {
68	        // Take the sheet's lock first, so two periods added at once cannot both pass the checks.
69	        sheets.lock(sheetId);
70	        if (from.isAfter(to)) {
71	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's from-date cannot be after its to-date.");
72	        }
73	        if (periods.findBySheetIdAndNameKey(sheetId, Period.keyOf(name)).isPresent()) {
74	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
75	        }
76	        if (periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
77	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period overlaps another period on this sheet.");
78	        }
79	        if (cap != null && cap < 1) {
80	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's claim cap must be at least 1.");
81	        }
82	        Period period = periods.saveAndFlush(new Period(sheetId, name, from, to, cap));
83	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
84	                + " from=" + period.getFromDate() + " to=" + period.getToDate()
85	                + (period.getClaimCap() != null ? " cap=" + period.getClaimCap() : ""));
86	        return period;
87	    }
88	
89	    /**
90	     * Generate one period per calendar month from the from-date's month to the to-date's month, each
91	     * running from the first to the last day of its month and named yyyy-mm, in month order. A month
92	     * whose name is already a period on the sheet, or whose days overlap one, is left out and the others
93	     * are still made. Refused when the to-date is before the from-date.
94	     */
95	    @Transactional
96	    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
97	        // Take the sheet's lock first, so no period added meanwhile slips past the checks.
98	        sheets.lock(sheetId);
99	        if (to.isBefore(from)) {
100	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date.");
101	        }
102	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
103	        List<Period> made = new ArrayList<>();
104	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
105	            addGenerated(sheetId, user, month.toString(), month.atDay(1), month.atEndOfMonth(), existing, made);
106	        }
107	        return made;
108	    }
109	
110	    /**
111	     * Generate the four calendar quarters of {@code year}, each running from the first day of its first
112	     * month to the last day of its third and named yyyy-Q1 to yyyy-Q4, in order. A quarter whose name is
113	     * already a period on the sheet, or whose days overlap one, is left out and the others are still made.
114	     */
115	    @Transactional
116	    public List<Period> generateQuarters(String sheetId, String user, int year) {
117	        // Take the sheet's lock first, so no period added meanwhile slips past the checks.
118	        sheets.lock(sheetId);
119	        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromDateAsc(sheetId));
120	        List<Period> made = new ArrayList<>();
121	        for (int quarter = 1; quarter <= 4; quarter++) {
122	            YearMonth start = YearMonth.of(year, quarter * 3 - 2);
123	            addGenerated(sheetId, user, year + "-Q" + quarter, start.atDay(1), start.plusMonths(2).atEndOfMonth(),
124	                    existing, made);
125	        }
126	        return made;
127	    }
128	
129	    /** Add a generated period unless its name is taken or its days overlap an existing one, as the form would. */
130	    private void addGenerated(String sheetId, String user, String name, LocalDate first, LocalDate last,
131	            List<Period> existing, List<Period> made) {
132	        if (existing.stream().anyMatch(p -> p.getName().toLowerCase(Locale.ROOT).equals(Period.keyOf(name))
133	                || p.overlaps(first, last))) {
134	            return;
135	        }
136	        Period period = periods.saveAndFlush(new Period(sheetId, name, first, last));
137	        existing.add(period);
138	        made.add(period);
139	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + period.getName()
140	                + " from=" + period.getFromDate() + " to=" + period.getToDate());
141	    }
142	
143	    /**
144	     * Generate the twelve monthly periods of the fiscal year named FY{@code year}, from the first day of
145	     * the sheet's fiscal start month in that year, exactly as {@link #generate} does.
146	     */
147	    @Transactional
148	    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
149	        LocalDate first = sheets.lock(sheetId).fiscalYearStart(year);
150	        return generate(sheetId, user, first, first.plusYears(1).minusDays(1));
151	    }
152	
153	    /**
154	     * Close a period, fixing at this moment each person's due-total and carried figure (see {@link #carried})
155	     * for it and its own due-total, their sum. A person's is the sum of the due figures,
156	     * as computed now, of the claims due by in it that were OPEN, PENDING or SETTLED at the end of its last day by their status log, each at
157	     * the grade its person has in force on its date (a claim with no figure adds nothing), leaving out those still OPEN or PENDING and dated
158	     * within their person's hold or of a person whose retirement date is reached, unless bound by a statement, and those deferred on today. A soft-closed period closes with its figures
159	     * fixed afresh. Refused when the period is already closed, or for a role the sheet's permission matrix does not allow.
160	     */
161	    @Transactional
162	    public Period close(String sheetId, String user, long periodId) {
163	        // Take the sheet's lock first, so no claim in the period changes while its total is fixed.
164	        LocalDate today = sheets.lock(sheetId).getToday();
165	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
166	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
167	        if (!roles.permits(sheetId, user, "close")) {
168	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period.");
169	        }
170	        if (period.isClosed()) {
171	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed.");
172	        }
173	        return fix(sheetId, user, period, today, "");
174	    }
175	
176	    /**
177	     * Soft-close an open period: its due-total and each person's figure for it are fixed as on a close
178	     * (see {@link #close}), while claims due by in it can still be added and changed. Refused when the
179	     * period is already closed or soft-closed, or for a role the sheet's permission matrix does not
180	     * allow to close.
181	     */
182	    @Transactional
183	    public Period softClose(String sheetId, String user, long periodId) {
184	        LocalDate today = sheets.lock(sheetId).getToday();
185	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
186	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
187	        if (!roles.permits(sheetId, user, "close")) {
188	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period.");
189	        }
190	        if (period.isFixed()) {
191	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed or soft-closed.");
192	        }
193	        period.softClose(totals(sheetId, period, today), carried(sheetId, period, today));
194	        Period saved = periods.saveAndFlush(period);
195	        audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
196	                + " total=" + saved.getClosedTotal().toPlainString());
197	        return saved;
198	    }
199	
200	    /**
201	     * The sheet's today was changed: close, in order of their to-dates, each open period whose to-date
202	     * plus the sheet's grace days is before the new today, exactly as a close by hand would, its
203	     * PERIOD_CLOSED marked auto=yes. A soft-closed period keeps the figures fixed for it and is left as
204	     * it is. Nothing closes while the grace days are off.
205	     */
206	    @EventListener
207	    public void todayChanged(TodayChanged change) {
208	        if (change.graceDays() == null) {
209	            return;
210	        }
211	        LocalDate today = sheets.lock(change.sheetId()).getToday();
212	        List<Period> due = periods.findBySheetIdOrderByFromDateAsc(change.sheetId()).stream()
213	                .filter(p -> !p.isFixed() && p.getToDate().plusDays(change.graceDays()).isBefore(today))
214	                .sorted(Comparator.comparing(Period::getToDate))
215	                .toList();
216	        for (Period period : due) {
217	            fix(change.sheetId(), change.user(), period, today, " auto=yes");
218	        }
219	    }
220	
221	    /** Close an open or soft-closed period, fixing its totals as of today, and audit it with the given trailing fields. */
222	    private Period fix(String sheetId, String user, Period period, LocalDate today, String trailing) {
223	        period.close(totals(sheetId, period, today), carried(sheetId, period, today));
224	        Period saved = periods.saveAndFlush(period);
225	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
226	                + " total=" + saved.getClosedTotal().toPlainString() + trailing);
227	        return saved;
228	    }
229	
230	    /** Each person's due-total for the period as of today, by person id (see {@link #close}). */
231	    private Map<Long, BigDecimal> totals(String sheetId, Period period, LocalDate today) {
232	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
233	                .collect(Collectors.toMap(Person::getId, person -> person));
234	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
235	        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
236	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
237	            Person person = byId.get(claim.getPersonId());
238	            if (person == null || !period.contains(claim.getDueBy())) {
239	                continue;
240	            }
241	            ClaimStatus then = claim.statusAt(period.getToDate());
242	            if (then == null || !then.counts() || claim.isDeferredOn(today)
243	                    || (claim.getStatus().isOpen() && !claim.isStated() && person.leavesLive(today))) {
244	                continue;
245	            }
246	            BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()));
247	            if (figure != null) {
248	                totals.merge(person.getId(), figure, BigDecimal::add);
249	            }
250	        }
251	        return totals;
252	    }
253	
254	    /**
255	     * Each person's carried figure for the period as of today, by person id: the sum of the due figures,
256	     * as computed now, of their claims due by in a period ending before this one starts that were OPEN or
257	     * PENDING at the end of this one's last day by their status log, each at the grade its person has in
258	     * force on its date, leaving out the same claims as {@link #totals}, plus their opening balance for it.
259	     */
260	    private Map<Long, BigDecimal> carried(String sheetId, Period period, LocalDate today) {
261	        List<Period> all = periods.findBySheetIdOrderByFromDateAsc(sheetId);
262	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
263	                .collect(Collectors.toMap(Person::getId, person -> person));
264	        Map<Long, BigDecimal> carried = new LinkedHashMap<>();
265	        byId.keySet().forEach(id -> carried.put(id,
266	                period.getPersonOpenings().getOrDefault(id, BigDecimal.ZERO).setScale(2)));
267	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
268	            Person person = byId.get(claim.getPersonId());
269	            boolean earlier = all.stream().filter(p -> p.contains(claim.getDueBy())).findFirst()
270	                    .map(own -> own.getToDate().isBefore(period.getFromDate())).orElse(false);
271	            if (person == null || !earlier) {
272	                continue;
273	            }
274	            ClaimStatus then = claim.statusAt(period.getToDate());
275	            if (then == null || !then.isOpen() || claim.isDeferredOn(today)
276	                    || (claim.getStatus().isOpen() && !claim.isStated() && person.leavesLive(today))) {
277	                continue;
278	            }
279	            BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()));
280	            if (figure != null) {
281	                carried.merge(person.getId(), figure, BigDecimal::add);
282	            }
283	        }
284	        return carried;
285	    }
286	
287	    /**
288	     * Reopen a closed or soft-closed period: its due-total is live again, the claims due by in it counting at their
289	     * current figures. Refused for a role the sheet's permission matrix
290	     * does not allow (anyone but a steward by default), when the period is neither closed nor soft-closed,
291	     * and while it is locked.
292	     */
293	    @Transactional
294	    public Period reopen(String sheetId, String user, long periodId) {
295	        LocalDate today = sheets.lock(sheetId).getToday();
296	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
297	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
298	        if (!roles.permits(sheetId, user, "reopen")) {
299	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reopen a period.");
300	        }
301	        if (!period.isFixed()) {
302	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is not closed.");
303	        }
304	        if (period.isLocked()) {
305	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is locked.");
306	        }
307	        period.reopen();
308	        Period saved = periods.saveAndFlush(period);
309	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
310	        return saved;
311	    }
312	
313	    /**
314	     * Lock or unlock a period: a locked period cannot be reopened. Refused for anyone but a steward,
315	     * when locking a period already locked, and when unlocking one not locked.
316	     */
317	    @Transactional
318	    public Period lock(String sheetId, String user, long periodId, boolean lock) {
319	        sheets.lock(sheetId);
320	        Period period = periods.findByIdAndSheetId(periodId, sheetId)
321	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
322	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
323	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may lock or unlock a period.");
324	        }
325	        if (period.isLocked() == lock) {
326	            throw new ResponseStatusException(HttpStatus.CONFLICT,
327	                    lock ? "The period is already locked." : "The period is not locked.");
328	        }
329	        period.setLocked(lock);
330	        Period saved = periods.saveAndFlush(period);
331	        audit.recordOnCommit((lock ? "PERIOD_LOCKED" : "PERIOD_UNLOCKED") + " sheet=" + sheetId + " by=" + user
332	                + " period=" + saved.getName());
333	        return saved;
334	    }
335	
336	    /**
337	     * Give out the number for a claim due by a date (its due-by) as it is opened, holding the sheet's lock until
338	     * the caller's transaction ends. While the sheet numbers by period (see {@link Sheet#numbersByPeriod})
339	     * it is the next within the period the date falls in, {@code <period name>-<n>}, or {@code X-<n>}
340	     * when it falls in none; otherwise it is the next sheet-wide number of the sheet's tree within the
341	     * fiscal year (by the sheet's fiscal start month) the date falls in, {@code FY<year>-<n>}, after the
342	     * last given in that fiscal year on any sheet of it. The tree's root is locked too, so the sheets of
343	     * a tree take their numbers one at a time.
344	     */
345	    @Transactional
346	    public String nextClaimNumber(String sheetId, LocalDate date) {
347	        Sheet sheet = sheets.lock(sheetId);
348	        if (!sheet.numbersByPeriod()) {
349	            List<String> tree = sheets.tree(sheetId);
350	            sheets.lock(tree.get(0));
351	            int year = sheet.fiscalYearOf(date);
352	            int lastInTree = tree.stream().filter(id -> !id.equals(sheetId))
353	                    .mapToInt(id -> sheets.load(id).getLastClaimNumberIn(year)).max().orElse(0);
354	            return "FY" + year + "-" + sheet.nextClaimNumberIn(year, lastInTree);
355	        }
356	        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
357	                .filter(p -> p.contains(date))
358	                .findFirst()
359	                .map(p -> p.getName() + "-" + p.nextClaimNumber())
360	                .orElseGet(() -> "X-" + sheet.nextUnperiodClaimNumber());
361	    }
362	
363	    /** The name of the period a date falls in on the sheet; null when it falls in none. */
364	    @Transactional(readOnly = true)
365	    public String periodOn(String sheetId, LocalDate date) {
366	        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
367	                .filter(p -> p.contains(date))
368	                .findFirst()
369	                .map(Period::getName)
370	                .orElse(null);
371	    }
372	
373	    /** Whether the date falls inside one of the sheet's soft-closed periods. */
374	    @Transactional(readOnly = true)
375	    public boolean softClosedOn(String sheetId, LocalDate date) {
376	        return periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
377	                .anyMatch(p -> p.isSoftClosed() && p.contains(date));
378	    }
379	
380	    /**
381	     * Refuse opening a claim due by a date (its due-by) inside a period with a claim cap when its person
382	     * already has that many OPEN or PENDING claims due by in the period.
383	     */
384	    public void refuseIfCapped(String sheetId, Claim claim) {
385	        periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
386	                .filter(p -> p.getClaimCap() != null && p.contains(claim.getDueBy()))
387	                .findFirst()
388	                .ifPresent(period -> {
389	                    long open = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()).stream()
390	                            .filter(c -> !c.getId().equals(claim.getId()) && c.getStatus().isOpen()
391	                                    && period.contains(c.getDueBy()))
392	                            .count();
393	                    if (open >= period.getClaimCap()) {
394	                        throw new ResponseStatusException(HttpStatus.CONFLICT, "The person already has "
395	                                + period.getClaimCap() + " open claims in period " + period.getName() + ".");
396	                    }
397	                });
398	    }
399	
400	    /** Refuse a change to a claim due by a date (its due-by) inside one of the sheet's closed periods. */
401	    public void refuseIfClosed(String sheetId, LocalDate date) {
402	        if (periods.findBySheetIdAndClosedTrue(sheetId).stream().anyMatch(p -> p.contains(date))) {
403	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is due by inside a closed period.");
404	        }
405	    }
